import unittest

MAIN_TERM_CAP_REGULAR = 25
MAIN_TERM_CAP_ADVANCED = 22
SUMMER_TERM_CAP = 12

def credit_cap(gpa: float, is_summer: bool, advanced_program: bool = False) -> int:
    if gpa < 0 or gpa > 10:
        raise ValueError("GPA must be on the 10-point scale")
    if is_summer:
        return SUMMER_TERM_CAP
    return MAIN_TERM_CAP_ADVANCED if advanced_program else MAIN_TERM_CAP_REGULAR

class TestCreditCap(unittest.TestCase):
    def test_summer(self):
        self.assertEqual(credit_cap(8.0, True), 12)
    def test_main_regular(self):
        self.assertEqual(credit_cap(7.0, False), 25)
    def test_main_advanced(self):
        self.assertEqual(credit_cap(7.0, False, advanced_program=True), 22)
    def test_invalid_gpa(self):
        with self.assertRaises(ValueError):
            credit_cap(11, False)

if __name__ == "__main__":
    unittest.main()

The regulation does not tie the cap to GPA, so the GPA argument is only validated [[qd-1175-2021/d7/k2/b]].
